Drizzle with honey', NULL, NULL, 270, 'estimate', 1, 0, 1, '["sweet","cute","gluten-free"]', '2026-10-29T11:01:27.151Z', '2026-10-29T11:01:27.151Z');
INSERT INTO ingredients (name, measure, quantity, unit, RecipeId, createdAt, updatedAt) SELECT json_extract(j.value,'$.name'), json_extract(j.value,'$.measure'), json_extract(j.value,'$.quantity'), json_extract(j.value,'$.unit'), r.id, '2026-10-29T11:01:27.151Z', '2026-10-29T11:01:27.151Z' FROM json_each('[{"name":"yogurt","measure":"300 g","quantity":300,"unit":"g"},{"name":"strawberry","measure":"8","quantity":8,"unit":null},{"name":"oats","measure":"0.5 cup","quantity":0.5,"unit":"cup"},{"name":"honey","measure":"2 tbsp","quantity":2,"unit":"tbsp"}]') j, (SELECT id FROM recipes WHERE source = 'seed' AND externalId = 'strawberry-yogurt-parfait') r WHERE changes() > 0;
